//! Finite original47 native union; complete ABI digests, never family-name selection.
use super::{CubinKernelManifest, VerifiedCubin, failure};
use cubecl_core::server::ServerError;

pub(super) fn require(
    image: &VerifiedCubin,
    manifest: &CubinKernelManifest,
) -> Result<(), ServerError> {
    match (image.derived_from(), image.captured_from()) {
        (Some(pin), None) => {
            pin.require_image(image.byte_len(), image.sha256(), image.binary_sm())?
        }
        (None, Some(pin)) => {
            pin.require_image(image.byte_len(), image.sha256(), image.binary_sm())?
        }
        _ => {
            return Err(failure(
                "canonical47 exact one sealed original image provenance",
            ));
        }
    }
    require_record(
        image.sha256(),
        image.byte_len(),
        image.binary_sm(),
        manifest,
    )
}
fn require_record(
    sha: [u8; 32],
    bytes: usize,
    sm: u8,
    manifest: &CubinKernelManifest,
) -> Result<(), ServerError> {
    let digest = super::attention_policy::digest(manifest);
    if !RULES.iter().any(|rule| *rule == (sha, bytes, sm, digest)) {
        return Err(failure(
            "canonical47 complete original image/geometry/scalar/stride/pointer/access ABI",
        ));
    }
    Ok(())
}
